CREATE OR REPLACE FUNCTION public.raxzi_claim_key() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed text; BEGIN UPDATE public.generated_keys SET is_active=false WHERE id=(SELECT id FROM public.generated_keys WHERE is_active=true ORDER BY created_at ASC FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING key_value INTO claimed; RETURN claimed; END; $$; REVOKE ALL ON FUNCTION public.raxzi_claim_key() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.raxzi_claim_key() TO service_role; ALTER TABLE public.generated_keys ENABLE ROW LEVEL SECURITY; ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY; INSERT INTO public.site_settings(id,channel_url,whatsapp_number) VALUES(true,'','') ON CONFLICT(id) DO NOTHING;